const progress=document.querySelector('.scroll-progress');let scrollPending=false;function paintScroll(){const range=document.documentElement.scrollHeight-innerHeight;if(progress)progress.style.width=(range>0?scrollY/range*100:0)+'%';scrollPending=false;}addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(paintScroll);}},{passive:true});paintScroll();
const glow=document.querySelector('.cursor-glow');if(matchMedia('(pointer:fine)').matches){addEventListener('pointermove',event=>{if(!reduced&&glow){glow.style.left=event.clientX+'px';glow.style.top=event.clientY+'px';}},{passive:true});document.querySelectorAll('.project').forEach(card=>{card.addEventListener('pointermove',event=>{if(reduced)return;const rect=card.getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width-.5;const y=(event.clientY-rect.top)/rect.height-.5;card.style.transform=`perspective(1000px) rotateY(${x*5}deg) rotateX(${-y*4}deg)`;});card.addEventListener('pointerleave',()=>card.style.transform='');});}
