const servicesToggle=document.querySelector('.services-toggle');const servicesMenu=document.querySelector('#services-menu');function closeServices(){if(servicesMenu)servicesMenu.hidden=true;servicesToggle?.setAttribute('aria-expanded','false');}servicesToggle?.addEventListener('click',()=>{const open=servicesToggle.getAttribute('aria-expanded')!=='true';servicesToggle.setAttribute('aria-expanded',String(open));servicesMenu.hidden=!open;});document.addEventListener('click',event=>{if(!event.target.closest('.nav-services'))closeServices();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&servicesToggle?.getAttribute('aria-expanded')==='true'){closeServices();servicesToggle.focus();}});
// A page-specific deck of section shortcuts.
const es=document.documentElement.lang==='es';const deck=document.createElement('aside');deck.className='corner-deck';deck.setAttribute('aria-label',es?'Navegación de secciones':'Section navigation');const deckButton=document.createElement('button');deckButton.className='corner-deck-toggle';deckButton.type='button';deckButton.setAttribute('aria-expanded','false');deckButton.setAttribute('aria-controls','corner-deck-panel');deckButton.setAttribute('aria-label',es?'Abrir cartas de navegación':'Open navigation cards');deckButton.innerHTML='<span aria-hidden="true">✦</span>';const deckLabel=document.createElement('span');deckLabel.className='corner-deck-label';deckLabel.textContent=es?'EXPLORAR':'EXPLORE';const deckPanel=document.createElement('div');deckPanel.id='corner-deck-panel';deckPanel.className='corner-deck-panel';deckPanel.hidden=true;const deckTitle=document.createElement('p');deckTitle.textContent=es?'En esta página':'On this page';const deckCards=document.createElement('div');deckCards.className='corner-deck-cards';const main=document.querySelector('main');if(main&&!main.id)main.id='main';const targets=[{id:'main',label:es?'Volver arriba':'Back to top'}];const used=new Set();document.querySelectorAll('main h2').forEach((heading,index)=>{const section=heading.closest('section')||heading.parentElement;if(!section||used.has(section))return;used.add(section);if(!section.id)section.id='chapter-'+(index+1);const label=heading.textContent.trim().replace(/\s+/g,' ');if(label)targets.push({id:section.id,label});});targets.slice(0,9).forEach((target,index)=>{const a=document.createElement('a');a.href='#'+target.id;const number=document.createElement('span');number.textContent=String(index+1).padStart(2,'0')+' ✦';const label=document.createElement('b');label.textContent=target.label;a.append(number,label);a.addEventListener('click',()=>setDeck(false));deckCards.append(a);});deckPanel.append(deckTitle,deckCards);deck.append(deckPanel,deckButton,deckLabel);document.body.append(deck);function setDeck(open){deckPanel.hidden=!open;deckButton.setAttribute('aria-expanded',String(open));deckButton.setAttribute('aria-label',es?(open?'Cerrar cartas de navegación':'Abrir cartas de navegación'):(open?'Close navigation cards':'Open navigation cards'));}deckButton.addEventListener('click',()=>setDeck(deckButton.getAttribute('aria-expanded')!=='true'));document.addEventListener('click',event=>{if(!deck.contains(event.target))setDeck(false);});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!deckPanel.hidden){setDeck(false);deckButton.focus();}});
