// Additional landmarks for pages whose content has no section headings.
const extraLandmarks=[['.project-grid',es?'Proyectos':'Projects'],['.full-service-deck',es?'Servicios':'Services'],['.pricing-grid',es?'Paquetes':'Packages'],['#contact-options',es?'Contacto por correo':'Email contact'],['.case-image',es?'Vista del proyecto':'Project preview'],['.service-detail',es?'Qué incluye':'What is included']];extraLandmarks.forEach(([selector,label],index)=>{const element=document.querySelector('main '+selector);if(!element)return;const anchor=element.closest('section')||element;if(!anchor.id)anchor.id='landmark-'+index;if(deckCards.querySelector('a[href="#'+anchor.id+'"]'))return;const a=document.createElement('a');a.href='#'+anchor.id;const number=document.createElement('span');number.textContent='✦';const text=document.createElement('b');text.textContent=label;a.append(number,text);a.addEventListener('click',()=>setDeck(false));deckCards.append(a);});
