const curated=[['.work-section',es?'Proyectos':'Projects'],['.spellbook',es?'Servicios':'Services'],['.studio-section',es?'Sobre Laura':'About Laura'],['.home-process-rich',es?'Proceso':'Process'],['.home-investment-rich',es?'Precios':'Pricing'],['.closing',es?'Contacto':'Contact']];const otherSections=[['.project-grid',es?'Proyectos':'Projects'],['.full-service-deck',es?'Servicios':'Services'],['.service-detail',es?'Detalles del servicio':'Service details'],['.pricing-grid',es?'Paquetes':'Packages'],['.care-content',es?'Mantenimiento':'Maintenance'],['.plugin-care',es?'Localización':'Localization'],['.career-section',es?'Experiencia':'Experience'],['#contact-options',es?'Correo':'Email'],['.closing',es?'Contacto':'Contact']];const choices=document.querySelector('.immersive-hero')?curated:otherSections;deckCards.replaceChildren();choices.forEach(([selector,label],index)=>{const section=document.querySelector('main '+selector);if(!section)return;const target=section.closest('section')||section;if(!target.id)target.id='explore-'+index;if(deckCards.querySelector('a[href="#'+target.id+'"]'))return;const a=document.createElement('a');a.href='#'+target.id;const n=document.createElement('span');n.textContent=String(deckCards.children.length+1).padStart(2,'0');const b=document.createElement('b');b.textContent=label;a.append(n,b);a.addEventListener('click',()=>{setDeck(false);target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});deckCards.append(a);});if(!deckCards.children.length){const a=document.createElement('a');a.href='#main';a.textContent=es?'Volver arriba':'Back to top';deckCards.append(a);}deckTitle.textContent=es?'Ir a una sección':'Jump to a section';
const projectHint=document.querySelector('#project-hint');const projectDescriptions={'webflow-development':es?'Sitios Webflow a medida, pensados para tu marca.':'Custom Webflow websites, designed around your brand.','wordpress-oxygen':es?'WordPress con Oxygen para un sitio flexible y fácil de actualizar.':'WordPress with Oxygen for a flexible, editable website.','webflow-cms':es?'Colecciones y plantillas que tu equipo puede gestionar.':'Collections and templates your team can manage.'};document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-project]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));if(projectHint)projectHint.textContent=projectDescriptions[button.dataset.project];const contactLink=document.querySelector('.immersive-copy .hero-actions .text-link');if(contactLink){contactLink.href=(es?'/es':'')+'/contact/?service='+button.dataset.project;contactLink.textContent=es?'Hablemos de tu proyecto ↗':'Let’s discuss your project ↗';}}));
if(document.querySelector('.rich-text')){deckCards.replaceChildren();const articleLinks=[['why',es?'Motivo':'Why migrate'],['inventory',es?'Inventario':'Inventory'],['urls','URLs'],['cms','CMS'],['journey',es?'Pruebas':'Checks'],['launch',es?'Lanzamiento':'Launch'],['references',es?'Fuentes':'Sources']];articleLinks.forEach(([id,label],index)=>{const target=document.getElementById(id);if(!target)return;const a=document.createElement('a');a.href='#'+id;const n=document.createElement('span');n.textContent=String(index+1).padStart(2,'0');const b=document.createElement('b');b.textContent=label;a.append(n,b);a.addEventListener('click',()=>{setDeck(false);target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});deckCards.append(a);});}
const shareStatus=document.querySelector('.share-status');const copyArticle=document.querySelector('.copy-article-link');copyArticle?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(copyArticle.dataset.url);if(shareStatus)shareStatus.textContent=es?'Enlace copiado.':'Link copied.';}catch{if(shareStatus){shareStatus.replaceChildren();const text=document.createElement('span');text.textContent=es?'Copia este enlace: ':'Copy this link: ';const input=document.createElement('input');input.readOnly=true;input.value=copyArticle.dataset.url;input.setAttribute('aria-label',es?'Enlace del artículo':'Article link');shareStatus.append(text,input);input.focus();input.select();}}});const nativeShare=document.querySelector('.native-share');if(nativeShare&&navigator.share){nativeShare.hidden=false;nativeShare.addEventListener('click',async()=>{try{await navigator.share({title:document.querySelector('h1')?.textContent||document.title,url:copyArticle?.dataset.url||location.href});}catch(error){if(error.name!=='AbortError'&&shareStatus)shareStatus.textContent=es?'Puedes usar los enlaces para compartir.':'You can use the sharing links instead.';}});}
function updateExploreDirections(){const marker=Math.min(innerHeight*.4,300);deckCards.querySelectorAll('a[href^="#"]').forEach(link=>{const section=document.getElementById(link.hash.slice(1));if(!section)return;const rect=section.getBoundingClientRect();const current=rect.top<=marker&&rect.bottom>marker;const direction=current?'•':rect.top<marker?'↑':'↓';link.dataset.direction=direction;link.dataset.current=String(current);if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');const text=link.querySelector('b')?.textContent||link.textContent;link.setAttribute('aria-label',text+(current?(es?', sección actual':', current section'):direction==='↑'?(es?', arriba':', above'):(es?', abajo':', below')));});}let exploreFrame=false;addEventListener('scroll',()=>{if(!exploreFrame){exploreFrame=true;requestAnimationFrame(()=>{updateExploreDirections();exploreFrame=false;});}},{passive:true});addEventListener('resize',updateExploreDirections);deckButton.addEventListener('click',updateExploreDirections);updateExploreDirections();

// Keep one FAQ expanded, including browsers without named-details support.
document.querySelectorAll('.faq-list').forEach(list=>{
  const items=[...list.querySelectorAll('details')];
  items.forEach(item=>{
    item.querySelector('summary')?.addEventListener('click',()=>{
      if(!item.open)items.forEach(other=>{if(other!==item)other.open=false;});
    });
    item.addEventListener('toggle',()=>{
      if(item.open)items.forEach(other=>{if(other!==item)other.open=false;});
    });
  });
});
